def iso_week(y, m, d):
    def is_leap_year(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def day_of_year(y, m, d):
        if m == 1:
            return d
        else:
            days_in_month = [31, 28 + is_leap_year(y), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            return d + sum(days_in_month[:m-1])

    doy = day_of_year(y, m, d)
    if m == 1 and doy == 7:
        return 1
    return ((doy + 6) // 7) + 1
```
